CREATE OR REPLACE FUNCTION pronto_private.guard_archived_business_activation() RETURNS trigger LANGUAGE plpgsql SET search_path TO '' AS $f$ BEGIN IF new.status='active' AND (new.archived_at IS NOT NULL OR new.removed_at IS NOT NULL) THEN RAISE EXCEPTION 'archived_business_requires_restore' USING errcode='42501'; END IF; RETURN new; END $f$; DROP TRIGGER IF EXISTS pronto_guard_archived_business_activation ON public.pronto_businesses; CREATE TRIGGER pronto_guard_archived_business_activation BEFORE INSERT OR UPDATE ON public.pronto_businesses FOR EACH ROW EXECUTE FUNCTION pronto_private.guard_archived_business_activation(); REVOKE ALL ON FUNCTION pronto_private.guard_archived_business_activation() FROM public,anon,authenticated;